# -*- coding: utf-8 -*-
def _cl(lines, first):
    out = []
    for i, s in enumerate(lines):
        a, b = s.split(' | ') if ' | ' in s else s.split('|')
        who = first if i % 2 == 0 else ('Y' if first != 'Y' else 'P')
        out.append("%s: %s | %s" % (who, a.strip(), b.strip()))
    return out

def E(n, t, s, city, sc, rs, desc, name, face, emo, mission, hook, goal, v, chat, tap, swap, chat2, sl, real, recap):
    ch = _cl(chat, 'P')
    tp = []
    for q, qp, opts, ans, quote in tap:
        idx = [i for i, l in enumerate(ch) if quote in l]
        assert idx, (n, quote)
        i = idx[0]
        tp.append((q, qp, opts, ans, i, "%s: “%s”" % (ch[i][0], quote)))
    sname, slines, gloss, keys = sl
    return dict(n=n, t=t, s=s, city=city, sc=sc, rs=rs, desc=desc, name=name, face=face, emo=emo, mission=mission,
                hook=hook, goal=goal, v=v, chat=ch, tap=tp, swap=swap, chat2=_cl(chat2, 'Y'),
                slang=(sname, ["🗣️", "#AE3EC9"], _cl(slines, 'F'), gloss, keys), real=real, recap_slang=recap)
